-- Isolated PostgreSQL fixture: Supabase roles/auth/storage and the existing
-- columns used by the production migrations. Never connects to the live app.
CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role;
CREATE SCHEMA auth; CREATE SCHEMA storage;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid $$;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE TABLE profiles(id uuid PRIMARY KEY, name text, username text, avatar_url text, avatar_color text, initials text, is_verified boolean);
CREATE TABLE circles(id uuid PRIMARY KEY, creator_id uuid, is_private boolean DEFAULT false, subscription_enabled boolean DEFAULT true, subscription_price integer DEFAULT 10, name text, avatar_url text);
CREATE TABLE circle_members(circle_id uuid, user_id uuid, status text DEFAULT 'active');
CREATE FUNCTION is_circle_member(uuid,uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER AS $$ SELECT EXISTS(SELECT 1 FROM circle_members WHERE circle_id=$1 AND user_id=$2 AND status='active') $$;
CREATE FUNCTION is_any_admin(uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT $1 = '00000000-0000-0000-0000-000000000099'::uuid $$;
CREATE FUNCTION is_post_audience(uuid,uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT $1=$2 $$;
CREATE TABLE follows(follower_id uuid, following_id uuid);
CREATE TABLE posts(id uuid PRIMARY KEY, circle_id uuid, user_id uuid, content text, media_url text, media_urls text[], cover_image_url text, voice_url text, original_pdf_url text, is_premium boolean DEFAULT false, premium_price integer, is_sponsored boolean DEFAULT false, visibility text DEFAULT 'public', created_at timestamptz DEFAULT now(), post_type text, location_text text, media_alt text, media_color_from text, media_color_to text, tags text[]);
CREATE TABLE post_stats(post_id uuid, likes_count integer DEFAULT 0, comments_count integer DEFAULT 0, shares_count integer DEFAULT 0, saves_count integer DEFAULT 0);
ALTER TABLE posts ADD COLUMN has_tips_enabled boolean;
CREATE TABLE likes(post_id uuid, user_id uuid, reaction_type text);
CREATE TABLE saves(post_id uuid, user_id uuid);
CREATE TABLE circle_tips(post_id uuid, tipper_id uuid);
CREATE TABLE circle_videos(id uuid PRIMARY KEY, circle_id uuid, user_id uuid, title text, video_url text, thumbnail_url text, is_premium boolean DEFAULT false, price integer, created_at timestamptz DEFAULT now());
CREATE TABLE circle_resources(id uuid PRIMARY KEY, circle_id uuid, uploader_id uuid, title text, file_url text, is_premium boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE circle_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), circle_id uuid, user_id uuid, status text DEFAULT 'active', started_at timestamptz DEFAULT now(), expires_at timestamptz, updated_at timestamptz DEFAULT now(), UNIQUE(circle_id,user_id));
CREATE TABLE post_unlocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid, user_id uuid, amount_paid integer, UNIQUE(post_id,user_id));
CREATE TABLE video_unlocks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), video_id uuid, user_id uuid, amount_paid integer, UNIQUE(video_id,user_id));
CREATE TYPE coin_transaction_type AS ENUM ('subscription','premium_unlock','premium_earning','refund','tip_sent','tip_received','service_payment','service_earned','event_payment','event_earned');
CREATE TABLE coin_wallets(user_id uuid PRIMARY KEY, balance integer DEFAULT 0, total_spent integer DEFAULT 0, total_earned integer DEFAULT 0, updated_at timestamptz DEFAULT now());
CREATE TABLE coin_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, amount integer, type coin_transaction_type, reference_id uuid, description text, balance_after integer);
CREATE TABLE circle_events(id uuid PRIMARY KEY, circle_id uuid, creator_id uuid, price numeric, status text DEFAULT 'upcoming', max_attendees integer, event_date date DEFAULT current_date, meeting_url text, recording_url text);
CREATE TABLE circle_event_attendees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid, user_id uuid, status text, payment_status text, UNIQUE(event_id,user_id));
CREATE TABLE circle_services(id uuid PRIMARY KEY, circle_id uuid, provider_id uuid, price numeric, is_active boolean DEFAULT true);
CREATE TABLE circle_service_bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid, user_id uuid, booking_date date, booking_time time, member_name text, member_email text, member_phone text, notes text, payment_status text, status text);
ALTER TABLE circle_events ENABLE ROW LEVEL SECURITY; CREATE POLICY existing_events_select ON circle_events FOR SELECT USING(true);
CREATE TABLE storage.buckets(id text PRIMARY KEY, public boolean);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), bucket_id text, name text, owner_id text, metadata jsonb);
INSERT INTO storage.buckets VALUES ('post-media',true),('circle-videos',true),('circle-resources',false);
ALTER TABLE posts ENABLE ROW LEVEL SECURITY; CREATE POLICY existing_posts_select ON posts FOR SELECT USING (true);
ALTER TABLE circle_videos ENABLE ROW LEVEL SECURITY; CREATE POLICY existing_videos_select ON circle_videos FOR SELECT USING (true);
ALTER TABLE circle_resources ENABLE ROW LEVEL SECURITY; CREATE POLICY existing_resources_select ON circle_resources FOR SELECT USING (true);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY; CREATE POLICY existing_storage_select ON storage.objects FOR SELECT USING (true);
GRANT USAGE ON SCHEMA public,auth,storage TO authenticated,anon;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
GRANT SELECT ON ALL TABLES IN SCHEMA public,storage TO anon;
GRANT SELECT ON storage.objects TO authenticated;
